// Simula una BD con lista en memoria para poder ejecutar
import java.util.ArrayList;
import java.util.List;

class Estudiante {
    int id;
    String nombre;
    int edad;

    public Estudiante(int id, String nombre, int edad) {
        this.id = id;
        this.nombre = nombre;
        this.edad = edad;
    }
}

public class Main {
    public static void main(String[] args) {
        // Crear una lista para simular la tabla 'estudiantes'
        List<Estudiante> estudiantes = new ArrayList<>();

        // Inserta algunos estudiantes en la lista
        estudiantes.add(new Estudiante(1, "Juan", 20));
        estudiantes.add(new Estudiante(2, "María", 22));
        estudiantes.add(new Estudiante(3, "Pedro", 21));

        // Selecciona todos los estudiantes y muestra el resultado
        System.out.println("Estudiantes:");
        for (Estudiante estudiante : estudiantes) {
            System.out.println("ID: " + estudiante.id + ", Nombre: " + estudiante.nombre + ", Edad: " + estudiante.edad);
        }
    }
}
